function getDateParts(date, locale, timezone, useUTC = true) {
  if (useUTC) {
    const day = String(date.getUTCDate()).padStart(2, "0");
    const month = String(date.getUTCMonth() + 1).padStart(2, "0");
    const year = String(date.getUTCFullYear());
    const hours = String(date.getUTCHours()).padStart(2, "0");
    const minutes = String(date.getUTCMinutes()).padStart(2, "0");
    const seconds = String(date.getUTCSeconds()).padStart(2, "0");
    const monthLongFormatter2 = new Intl.DateTimeFormat(locale, {
      month: "long",
      timeZone: "UTC"
    });
    const monthShortFormatter2 = new Intl.DateTimeFormat(locale, {
      month: "short",
      timeZone: "UTC"
    });
    return {
      day,
      hours,
      minutes,
      month,
      monthLong: monthLongFormatter2.format(date),
      monthShort: monthShortFormatter2.format(date),
      seconds,
      year
    };
  }
  const options = {
    day: "2-digit",
    hour: "2-digit",
    hour12: false,
    minute: "2-digit",
    month: "2-digit",
    second: "2-digit",
    timeZone: timezone,
    year: "numeric"
  };
  const formatter = new Intl.DateTimeFormat(locale, options);
  const parts = formatter.formatToParts(date);
  const getPart = (type) => parts.find((p) => p.type === type)?.value ?? "";
  const monthLongFormatter = new Intl.DateTimeFormat(locale, {
    month: "long",
    timeZone: timezone
  });
  const monthShortFormatter = new Intl.DateTimeFormat(locale, {
    month: "short",
    timeZone: timezone
  });
  return {
    day: getPart("day"),
    hours: getPart("hour"),
    minutes: getPart("minute"),
    month: getPart("month"),
    monthLong: monthLongFormatter.format(date),
    monthShort: monthShortFormatter.format(date),
    seconds: getPart("second"),
    year: getPart("year")
  };
}
